files.replay/clock.py:
"""The clock the replay desk reads."""


def clock_name(line):
    head, _, _ = line.partition(":")
    return head.strip()

files.replay/holds.py:
"""Hold helpers for the replay desk."""
from replay.clock import clock_name


def hold_note(line):
    # REPLAY-HOLD: the hold rides on the annotation
    return clock_name(line)


def is_held(line):
    # REPLAY-HOLD: the desk reads the annotation off the line
    return "hold" in line
